const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const config = $('Load service configuration').first().json;
const supplied = String(headers['x-hackcure-secret'] || headers['X-HackCure-Secret'] || '');
if (!config.shared_secret || supplied !== config.shared_secret) throw new Error('Unauthorized webhook request');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(String(body.patient_id || '')) || !uuid.test(String(body.session_id || ''))) throw new Error('Invalid patient/session reference');
if (typeof body.message !== 'string' || !body.message.trim() || body.message.length > 4000) throw new Error('Invalid message');
if (typeof body.context_token !== 'string' || !/^[0-9a-f]{64}$/i.test(body.context_token)) throw new Error('Invalid context authorization');
const history = Array.isArray(body.history) ? body.history.slice(-39).filter(x => x && ['user','assistant'].includes(x.role) && typeof x.content === 'string').map(x => ({role:x.role, content:x.content.slice(0,4000)})) : [];
const numbers = Array.isArray(body.emergency_numbers) ? body.emergency_numbers.filter(x => x && typeof x.label === 'string' && typeof x.number === 'string').map(x => ({label:x.label.slice(0,50), number:x.number.slice(0,24)})) : [];
return [{json:{patient_id:body.patient_id, session_id:body.session_id, context_token:body.context_token, message:body.message.trim(), language:String(body.language || 'fr').slice(0,12), history, rolling_summary:String(body.rolling_summary || '').slice(0,1600), system_prompt:String(body.system_prompt || '').slice(0,20000), emergency_numbers:numbers}}];

const response = $input.first().json || {};
const request = $('Validate and minimize request').first().json;
const contextResponse = $('Load minimized patient context').first().json || {};
const context = typeof contextResponse.context === 'string' ? contextResponse.context.slice(0,7000) : '';
let raw = response.content?.filter(x => x.type === 'text').map(x => x.text).join('') || '';
let parsed = {};
try { parsed = JSON.parse((raw.match(/\{[\s\S]*\}/) || [])[0] || '{}'); } catch {}
let label = ['none','distress','self_harm_or_suicide_risk','medical_emergency','medication_change_request','off_topic'].includes(parsed.label) ? parsed.label : 'distress';
const text = request.message.toLowerCase();
const keywords = {self_harm_or_suicide_risk:['suicide','kill myself','end my life','self-harm','hurt myself','want to die','me tuer','suicid','me faire du mal','je veux mourir','نحب نموت','نقتل روحي','نأذي روحي'],medical_emergency:['can\'t breathe','cannot breathe','chest pain','overdose','unconscious','severe bleeding','du mal à respirer','douleur thoracique','surdose','ما نجمش نتنفس','وجيعة في صدري'],medication_change_request:['change my dose','stop taking','increase my dose','reduce my dose','skip my medication','changer ma dose','arrêter mon traitement','augmenter ma dose','نبدل الجرعة','نوقف الدواء'],off_topic:['price of a car','car price','used car cost','write me code','write code','écris-moi du code','help me code','politics','change my password','weather tomorrow','prix d\'une voiture','سعر سيارة','اكتبلي كود']};
for (const key of Object.keys(keywords)) if (keywords[key].some(x => text.includes(x))) { label=key; break; }
const bypass = ['self_harm_or_suicide_risk','medical_emergency','medication_change_request','off_topic'].includes(label);
let searchQuery = typeof parsed.search_query === 'string' ? parsed.search_query.slice(0,240) : '';
searchQuery = searchQuery.replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g,'').replace(/\b(?:\+?\d[\d\s().-]{7,}\d)\b/g,'').replace(/\b[0-9a-f]{8}-[0-9a-f-]{27,}\b/ig,'').trim();
const config = $('Load service configuration').first().json;
return [{json:{...request, context, triage_label:label, bypass, search_query:searchQuery || null, needs_search:!bypass && Boolean(searchQuery) && Boolean(config.tavily_key)}}];
